pub(crate) fn decode(payload:&store::io::IoPayload,control:&mut SqliteSnapshotControl<'_>,native_control:&mut semio_framework_value::NativeDecodeControl<'_>)->Result<SemioKitSnapshot,ValueError>{
 let limits=control.limits();crate::standards::v1::subsets::kit::io::sqlite::snapshot::admit_layout(limits)?;
 let size=match payload{store::io::IoPayload::Binary(value)=>value.len(),store::io::IoPayload::Text(value)=>value.len()};if size>limits.max_file_bytes{return Err(ValueError::new(ValueRefusalKind::OwnershipLimit,"Semio Kit native input exceeds file limit"))}
 control.allocation_stage_native(store::sqlite_snapshot::SqliteSnapshotPhase::DecodeNative,|remaining,checkpoint|{
  let native_before=native_control.owned_bytes();let result=native_control.scoped_maximum(native_before.checked_add(remaining).ok_or_else(||ValueError::new(ValueRefusalKind::OwnershipLimit,"native snapshot allowance overflow"))?,|native_control|{
  let result=(||->Result<SemioKitSnapshot,ValueError>{let result=match payload{
   store::io::IoPayload::Binary(value)=>{let body=store::semio_format::unwrap_binary_controlled(value,STDIO_SEMIOKIT_DOCUMENT_SCHEMA,store::semio_format::Component::Pack,1,native_control).map_err(store::semio_format::SemioError::into_value_error)?;binary(body,native_control,limits)?},
   store::io::IoPayload::Text(value)=>{let body=store::semio_format::split_text_preamble_controlled(value,STDIO_SEMIOKIT_DOCUMENT_SCHEMA,store::semio_format::Component::Dsl,1,native_control).map_err(store::semio_format::SemioError::into_value_error)?;document(body,native_control,limits)?}
  };let result=native::Owned::new(result);native_control.checkpoint()?;Ok(result.take())})();result});(result,native_control.owned_bytes().saturating_sub(native_before))
 })?
}
fn binary_reference(reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>)->Result<semio_framework_artifact_reference::ArtifactRef,ValueError>{let id=native::text(reader,control)?;let mut owner=native::Owned::new(semio_framework_artifact_reference::ArtifactRef{artifact_id:id,dialect:semio_framework_artifact_reference::ArtifactDialect{artifact_kind:String::new(),standard:String::new(),subset:String::new()}});owner.get_mut().dialect.artifact_kind=native::text(reader,control)?;owner.get_mut().dialect.standard=native::text(reader,control)?;owner.get_mut().dialect.subset=native::text(reader,control)?;Ok(owner.take())}
fn binary_child<S>(reader:&mut store::ByteReader<'_>,subset:&str,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<store::ArtifactChild<S>,ValueError>{native::entities(entities,1,limits)?;let mut child_id=native::Owned::new(native::text(reader,control)?);let mut target=native::Owned::new(binary_reference(reader,control)?);validate_semio_child_identity(child_id.get_mut(),target.get_mut(),subset).map_err(|error|ValueError::new(ValueRefusalKind::InvalidValue,error))?;Ok(store::ArtifactChild::new(child_id.take(),target.take()))}
