fn binary_connection(reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>)->Result<SemioKitConnection,ValueError>{let id=native::text(reader,control)?;let mut owner=native::Owned::new(SemioKitConnection{id,connecting_piece_id:String::new(),connecting_port:String::new(),connected_piece_id:String::new(),connected_port:String::new()});owner.get_mut().connecting_piece_id=native::text(reader,control)?;owner.get_mut().connecting_port=native::text(reader,control)?;owner.get_mut().connected_piece_id=native::text(reader,control)?;owner.get_mut().connected_port=native::text(reader,control)?;Ok(owner.take())}
fn binary_design(reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<SemioKitDesign,ValueError>{let id=native::Owned::new(native::text(reader,control)?);let name=native::text(reader,control)?;let mut owner=native::Owned::new(SemioKitDesign{id:id.take(),name,pieces:Vec::new(),connections:Vec::new()});owner.get_mut().pieces=native::binary_list(reader,control,limits,entities,|reader,control,_|binary_piece(reader,control))?;owner.get_mut().connections=native::binary_list(reader,control,limits,entities,|reader,control,_|binary_connection(reader,control))?;Ok(owner.take())}
fn binary_link(reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<store::ArtifactLink,ValueError>{native::entities(entities,1,limits)?;let target=binary_reference(reader,control)?;let mut owner=native::Owned::new(store::ArtifactLink{target,pin:store::LinkPin::Head,role:String::new()});owner.get_mut().pin=match reader.read_u8().map_err(|error|ValueError::new(ValueRefusalKind::InvalidValue,error.to_string()))?{0=>store::LinkPin::Head,1=>store::LinkPin::Checkpoint{id:native::text(reader,control)?},2=>{native::entities(entities,1,limits)?;let hash=native::text(reader,control)?;let mut blob=native::Owned::new(store::BlobRef{hash,size:0,media_type:String::new()});blob.get_mut().size=reader.read_varint_u64().map_err(|error|ValueError::new(ValueRefusalKind::InvalidValue,error.to_string()))?;blob.get_mut().media_type=native::text(reader,control)?;store::LinkPin::Snapshot{blob:blob.take()}},_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"Kit native invalid pin tag"))};owner.get_mut().role=native::text(reader,control)?;Ok(owner.take())}
pub(crate) fn binary(body:&[u8],control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits)->Result<SemioKitSnapshot,ValueError>{crate::standards::v1::subsets::kit::io::sqlite::snapshot::admit_binary(body,control,limits)?;let mut reader=store::ByteReader::new(body);if reader.read_u8().map_err(|error|ValueError::new(ValueRefusalKind::InvalidValue,error.to_string()))?!=1{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"Kit native unsupported format"))}let mut entities=0;native::entities(&mut entities,1,limits)?;let schema=native::text(&mut reader,control)?;let mut owner=native::Owned::new(SemioKitSnapshot{schema,types:Vec::new(),designs:Vec::new(),objects:Vec::new(),models:Vec::new(),properties:None,representations:Vec::new()});owner.get_mut().types=native::binary_list(&mut reader,control,limits,&mut entities,|reader,control,_|binary_type(reader,control))?;owner.get_mut().designs=native::binary_list(&mut reader,control,limits,&mut entities,|reader,control,entities|binary_design(reader,control,limits,entities))?;owner.get_mut().objects=native::binary_list(&mut reader,control,limits,&mut entities,|reader,control,entities|binary_child(reader,"object",control,limits,entities))?;owner.get_mut().models=native::binary_list(&mut reader,control,limits,&mut entities,|reader,control,entities|binary_child(reader,"model",control,limits,entities))?;owner.get_mut().properties=match reader.read_u8().map_err(|error|ValueError::new(ValueRefusalKind::InvalidValue,error.to_string()))?{0=>None,1=>{native::entities(&mut entities,1,limits)?;Some(binary_child(&mut reader,"value",control,limits,&mut entities)?)},_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"Kit native invalid optional child presence"))};owner.get_mut().representations=native::binary_list(&mut reader,control,limits,&mut entities,|reader,control,entities|binary_link(reader,control,limits,entities))?;if reader.remaining()!=0{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"Kit native trailing bytes"))}Ok(owner.take())}
fn text_reference(value:&str,control:&mut NativeDecodeControl<'_>)->Result<semio_framework_artifact_reference::ArtifactRef,ValueError>{let[id,kind,standard,subset]=native::record(value,control)?;let id=native::hex_text(id,control)?;let mut owner=native::Owned::new(semio_framework_artifact_reference::ArtifactRef{artifact_id:id,dialect:semio_framework_artifact_reference::ArtifactDialect{artifact_kind:String::new(),standard:String::new(),subset:String::new()}});owner.get_mut().dialect.artifact_kind=native::hex_text(kind,control)?;owner.get_mut().dialect.standard=native::hex_text(standard,control)?;owner.get_mut().dialect.subset=native::hex_text(subset,control)?;Ok(owner.take())}
