fn text_pin(value:&str,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<store::LinkPin,ValueError>{if value=="[h]"{return Ok(store::LinkPin::Head)}let inner=value.strip_prefix('[').and_then(|value|value.strip_suffix(']')).ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"Kit native pin requires brackets"))?;match inner.split_once(',').map(|(tag,_)|tag){Some("c")=>{let[_,id]=native::record(value,control)?;Ok(store::LinkPin::Checkpoint{id:native::hex_text(id,control)?})},Some("s")=>{native::entities(entities,1,limits)?;let[_,hash,size,media_type]=native::record(value,control)?;let size=control.scoped_stage(|control|{control.begin_stage(size.len())?;for _ in size.bytes(){control.step()?;}size.parse::<u64>().map_err(|_|ValueError::new(ValueRefusalKind::InvalidValue,"Kit native invalid blob size"))})?;let hash=native::hex_text(hash,control)?;let mut blob=native::Owned::new(store::BlobRef{hash,size,media_type:String::new()});blob.get_mut().media_type=native::hex_text(media_type,control)?;Ok(store::LinkPin::Snapshot{blob:blob.take()})},_=>Err(ValueError::new(ValueRefusalKind::InvalidValue,"Kit native invalid pin shape"))}}
